<!doctype html>
<html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><meta name="referrer" content="no-referrer"><title>Sponsorenlauf | ClubUnio</title><link rel="stylesheet" href="/css/sponsor-run.css"><script src="/js/sponsor-run-public.js" defer></script></head>
<body><main class="sr-public"><h1>Sponsorenlauf</h1><p id="sr-message" role="status">Link wird geprüft.</p><section id="sr-event" hidden><h2 id="sr-title"></h2><p id="sr-alias"></p><p id="sr-date"></p></section>
<form id="sr-confirm" hidden><button type="submit">Zusage verbindlich bestätigen</button></form>
<form id="sr-pledge" hidden>
<label>Sponsorname<input name="sponsor_name" maxlength="160" required autocomplete="name"></label>
<fieldset><legend>Zusage</legend><label>Art<select name="amount_type"><option value="per_lap">Pro Runde</option><option value="fixed">Fixbetrag</option></select></label><label>Betrag in Rappen<input name="amount_cents" type="number" min="1" max="10000000" step="1" required></label><label>Obergrenze in Rappen<input name="cap_cents" type="number" min="1" max="10000000" step="1"></label></fieldset>
<fieldset><legend>Rechnungsempfaenger</legend><label>Typ<select name="recipient_type"><option value="person">Person</option><option value="company">Firma</option></select></label><label>Firma<input name="company" maxlength="160" autocomplete="organization"></label><label>Vorname / Kontakt<input name="first_name" maxlength="100" required autocomplete="given-name"></label><label>Nachname<input name="last_name" maxlength="100" required autocomplete="family-name"></label><label>Strasse<input name="street" maxlength="160" required autocomplete="address-line1"></label><label>Hausnummer<input name="house_number" maxlength="20"></label><label>PLZ<input name="postal_code" maxlength="20" required autocomplete="postal-code"></label><label>Ort<input name="city" maxlength="100" required autocomplete="address-level2"></label><label>Land (ISO)<input name="country" minlength="2" maxlength="2" pattern="[A-Z]{2}" value="CH" required autocomplete="country"></label><label>E-Mail<input name="email" type="email" maxlength="254" required autocomplete="email"></label></fieldset>
<label class="sr-trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label>
<label class="sr-consent"><input type="checkbox" name="consent" required> Ich stimme der Verarbeitung meiner Angaben für diese Sponsorenzusage und Rechnung zu und bestätige die Zusage nach E-Mail-Bestätigung.</label><button type="submit">Bestätigung anfordern</button></form>
</main></body></html>
